// ── `the-in-graph-terminal-cannot-be-clicked-accurately-under-zoom` — the card is a constant SCREEN
//    size inside a world-positioned anchor that cancels the world scale. jsdom has no layout, so these
//    assert the SHAPE the fix depends on; whether a click then lands on the right cell is only
//    observable in a browser, and `e2e/xtermScale.spec.ts` is where that is measured. ──
describe("the screen-constant card (the-in-graph-terminal-cannot-be-clicked-accurately-under-zoom)", () => {
  /** The anchor is the card's parent — world-positioned, and the element the hook writes onto. */
  const anchorOf = (c: HTMLElement) => c.querySelector(".glance-card")!.parentElement as HTMLElement;
  const cardOf = (c: HTMLElement) => c.querySelector(".glance-card") as HTMLElement;

  it("anchors at the grid anchor's WORLD centre, and never at a zoom-multiplied position", () => {
    // The anchor's left/top carry no `zoom` term at all. That is what stops the card drifting during a
    // wheel gesture React has not committed yet — `view.scale` lands 120ms late (#4140), so a position
    // derived from it would slide for the whole zoom and snap at the end.
    const centre = anchorCentre(NODE);
    for (const zoom of [0.5, 1, 2.6]) {
      const { container, unmount } = render(
        <GlanceStreamMorph node={NODE} {...GRID} zoom={zoom} paneId="p:a" name="a" onClose={() => {}} />,
      );
      const a = anchorOf(container);
      expect(a.style.left).toBe(`${centre.x}px`);
      expect(a.style.top).toBe(`${centre.y}px`);
      expect(a.style.transformOrigin).toBe("0 0");
      unmount();
    }
  });

  it("sizes the OPEN card in SCREEN px — identical at every zoom", () => {
    vi.useFakeTimers();
    const seen = new Set<string>();
    for (const zoom of [0.28, 1, 2.6]) {
      const { container, unmount } = render(
        <GlanceStreamMorph node={NODE} {...GRID} zoom={zoom} paneId="p:a" name="a" onClose={() => {}} />,
      );
      act(() => { vi.advanceTimersByTime(20); });
      const card = cardOf(container);
      seen.add(`${card.style.width}x${card.style.height}`);
      unmount();
    }
    // ONE size across the whole zoom range — the property that keeps the terminal's cols/rows fixed, so
    // zooming never triggers the `fit()` + `pty_resize` storm that got #3524 reverted.
    expect([...seen]).toEqual([`${CELL_W}px x ${CELL_H}px`.replace(" x ", "x")]);
  });

  it("registers its anchor with the viewport's counterScale, and unregisters on unmount", () => {
    // The hook owns the inverse transform; the morph only says WHICH element needs it. A leaked
    // registration would keep writing a transform onto a detached node for the life of the page.
    const drop = vi.fn();
    const counterScale = vi.fn(() => drop);
    const { container, unmount } = render(
      <GlanceStreamMorph node={NODE} {...GRID} counterScale={counterScale} paneId="p:a" name="a" onClose={() => {}} />,
    );
    expect(counterScale).toHaveBeenCalledTimes(1);
    expect(counterScale.mock.calls[0][0]).toBe(anchorOf(container));
    unmount();
    expect(drop).toHaveBeenCalledTimes(1);
  });

  it("never writes `transform` on the anchor itself — that is the hook's, and one owner only", () => {
    // Naming it here too would give React a second opinion about the one value that must never disagree
    // with the world layer's own transform.
    const { container } = render(
      <GlanceStreamMorph node={NODE} {...GRID} zoom={2} paneId="p:a" name="a" onClose={() => {}} />,
    );
    expect(anchorOf(container).style.transform).toBe("");
  });

  it("reports a WORLD box that grows as the graph zooms out (#2662 still gets a true footprint)", () => {
    vi.useFakeTimers();
    const boxAt = (zoom: number) => {
      const onRect = vi.fn();
      const { unmount } = render(
        <GlanceStreamMorph node={NODE} {...GRID} zoom={zoom} paneId="p:a" name="a" onRect={onRect} onClose={() => {}} />,
      );
      act(() => { vi.advanceTimersByTime(20); });
      const reported = onRect.mock.calls.map((c) => c[0]).filter(Boolean);
      unmount();
      return reported[reported.length - 1];
    };
    // A fixed screen size covers MORE world when the world is drawn smaller. Reporting the nominal cell
    // instead is what let a zoomed-out panel cover the very nodes it was supposed to push aside.
    expect(boxAt(0.5).w).toBe(CELL_W * 2);
    expect(boxAt(1).w).toBe(CELL_W);
    expect(boxAt(2).w).toBe(CELL_W / 2);
  });

  it("resizes 1:1 with the pointer — the drag is no longer divided by the zoom", () => {
    vi.useFakeTimers();
    const onResizeCell = vi.fn();
    const { container } = render(
      <GlanceStreamMorph node={NODE} {...GRID} zoom={2} paneId="p:a" name="a" onResizeCell={onResizeCell} onClose={() => {}} />,
    );
    act(() => { vi.advanceTimersByTime(20); });
    const east = container.querySelector('[aria-label="Resize e"]') as HTMLElement;
    fireEvent.pointerDown(east, { clientX: 0, clientY: 0 });
    fireEvent.pointerMove(window, { clientX: 100, clientY: 0 });
    // 100 pointer px => 100 cell px, at zoom 2. The old code divided by the zoom and would say 50.
    expect(onResizeCell).toHaveBeenLastCalledWith(CELL_W + 100, CELL_H);
    fireEvent.pointerUp(window);
  });
});
